'use strict';
const promise=EldoriaPromiseModel;promise.observe(state);
const promiseCSS=document.createElement('link');promiseCSS.rel='stylesheet';promiseCSS.href='city-promise.css?v=1';document.head.append(promiseCSS);
const promiseBanner=document.createElement('section');promiseBanner.id='promiseBanner';promiseBanner.setAttribute('aria-label','Eldoria County’s Midnight Promise');promiseBanner.innerHTML='<div><span class="city-eyebrow">ELDORIA COUNTY’S FOUNDING ENCHANTMENT</span><strong>The Midnight Promise</strong><p id="promiseStatus"></p></div><button id="promiseOpen">Choose my midnight intention</button>';$('cityScene').before(promiseBanner);$('promiseOpen').onclick=promiseBoard;
let promiseWasActive=null;
function promiseRender(){const active=promise.active(state),c=promise.time(state);document.body.classList.toggle('promise-active',active);$('promiseStatus').textContent=active?'Midnight is here. What you begin with purpose finds its finest form.':'At 12:00–12:59 a.m., throughout the county, work becomes wonderful and answers come to light. '+(c?'World time: '+String(c.hour).padStart(2,'0')+':'+String(c.minute).padStart(2,'0')+'.':'');$('promiseOpen').textContent=active?'Let my intention become real':'My intentions & midnight journal';if(active){const h=$('heritageMagic');if(h&&heritage.ensure(state).magicOn)h.hidden=false;$('cityWeather').textContent='✧ THE MIDNIGHT PROMISE · '+weatherNames[c.weather];$('hint').textContent='The whole county is enchanted. Cook, create, learn, discover—or name an intention for midnight to fulfill.'}if(promiseWasActive!==active){promiseWasActive=active;if(promiseWasActive!==null&&active)cityMessage('Midnight has awakened throughout Eldoria County. Your purposeful work will find its perfect form.')}}
function promiseTargets(kind){const l=cityLife.ensure(state);if(kind==='quest')return cityLife.quests.filter(q=>!l.quests[q.id]?.complete).map(q=>[q.id,q.name]);if(kind==='home')return cityLife.upgrades.filter(u=>!l.upgrades[u.id]).map(u=>[u.id,u.name]);if(kind==='magic')return heritage.activities.filter(a=>a.spell&&!heritage.ensure(state).spells[a.spell]).map(a=>[a.spell,a.title]);if(kind==='friend')return cityLife.people.map(p=>[p.id,p.name]);return[]}
function promiseBoard(){const p=promise.ensure(state),active=promise.active(state);modal('The Midnight Promise','<span class="city-eyebrow">THE WHOLE COUNTY · EVERY PURPOSEFUL ACT</span><p class="life-dialogue">“At midnight, what you begin with purpose becomes its finest possibility.”</p><p>'+ (active?'The enchanted hour is here. Name an in-game purpose: midnight will make the dish wonderful, the work beautiful, the answer clear, or the goal accomplished.':'The Promise awakens every night from 12:00 to 12:59 a.m. in your selected world timezone. Your real clock keeps its time; your journal keeps what midnight gave you.')+'</p><div class="promise-form"><label>My in-game intention<input id="promisePurpose" maxlength="240" placeholder="What do you want to accomplish in Eldoria?"></label><label>Let midnight help me…<select id="promiseKind"></select></label><label id="promiseTargetLabel">My goal<select id="promiseTarget"></select></label></div><p id="promiseFeedback" role="status"></p><div id="promiseJournal"></div>');for(const [key,title]of Object.entries(promise.kinds)){const option=document.createElement('option');option.value=key;option.textContent=title;$('promiseKind').append(option)}if(p.intention)$('promisePurpose').value=p.intention;function targets(){const entries=promiseTargets($('promiseKind').value);$('promiseTargetLabel').hidden=entries.length===0;$('promiseTarget').replaceChildren();for(const [key,title]of entries){const o=document.createElement('option');o.value=key;o.textContent=title;$('promiseTarget').append(o)}}$('promiseKind').onchange=targets;targets();action('Let midnight fulfill my intention',()=>{const kind=$('promiseKind').value,target=$('promiseTarget').value,purpose=$('promisePurpose').value.trim();if(['quest','home','magic','friend'].includes(kind)&&!target){$('promiseFeedback').textContent='All goals of this kind are complete. Choose another intention.';return}const r=promise.fulfill(state,kind,target,purpose);if(!r.ok){$('promiseFeedback').textContent=r.reason;return}lifeCommit();promiseOutcome(r)});action('Remember this intention',()=>{p.intention=$('promisePurpose').value.trim().slice(0,240);persist();$('promiseFeedback').textContent='Your intention is saved for the next midnight.'});action('Open my perfect-work journal',promiseJournal);action('Open my midnight pantry',promisePantry);action('Return to the county',()=>{$('modal').close();cityDraw()});}
function promiseOutcome(r){modal('Midnight finds its finest form','<span class="promise-quality">PERFECT · THE MIDNIGHT PROMISE</span><h3>'+lifeEsc(r.title)+'</h3><p class="life-dialogue">'+lifeEsc(r.detail)+'</p>'+(r.item.purpose?'<p>Your intention: “'+lifeEsc(r.item.purpose)+'”</p>':'')+'<p>This result is saved in your midnight journal.</p>');if(r.item.kind==='home')action('See my finished cottage project',()=>heritageTravel('home','home'));if(r.item.kind==='magic')action('Cast my learned magic',()=>heritageBoard('spells'));if(r.item.kind==='answers')action('Follow the answer',lifeContinue);if(r.item.kind==='cook')action('Serve my wonderful dish',promisePantry);action('Choose another intention',promiseBoard);action('Enjoy the county',()=>{$('modal').close();cityDraw()})}
function promiseJournal(){const p=promise.ensure(state);modal('The midnight journal','<p>These are the creations, answers, acts of kindness and goals that found their finest form during Eldoria’s enchanted hour.</p>'+p.items.map(item=>'<article class="promise-journal-item"><span class="promise-quality">'+lifeEsc(item.quality)+' · '+lifeEsc(item.night)+'</span><h3>'+lifeEsc(item.title)+'</h3>'+(item.purpose?'<p>'+lifeEsc(item.purpose)+'</p>':'')+'</article>').join('')+(!p.items.length?'<p>Your first midnight promise is still waiting to be written.</p>':''));action('Choose an intention',promiseBoard);action('Open the midnight pantry',promisePantry)}
function promisePantry(){const bag=state.life?.bag||{};modal('Treasures made at midnight','<p>The finest work remains yours after the enchanted hour ends.</p><p>Wonderful midnight feasts: <strong>'+(bag['midnight feast']||0)+'</strong></p><p>Perfect handmade treasures: <strong>'+(bag['midnight masterwork']||0)+'</strong></p><p>Rare starlit moonflowers: <strong>'+(bag['starlit moonflower']||0)+'</strong></p>');if(bag['midnight feast']>0){for(const [share,text]of [[false,'Enjoy a wonderful feast'],[true,'Share a perfect feast with Fern']])action(text,()=>{const r=promise.meal(state,share);if(!r.ok)return;lifeCommit();modal(r.title,'<p>The dish is just as wonderful as it was at midnight.'+(share?' Fern remembers the kindness.':'')+'</p>');action('Back to my midnight pantry',promisePantry)})}action('Read my midnight journal',promiseJournal);action('Choose a new midnight purpose',promiseBoard)}
const promisePuzzleBefore=lifePuzzle;lifePuzzle=function(id,title,submit,again){const puzzle=cityLife.puzzle(id),wrapped=response=>{const r=submit(promise.guide(state,puzzle,response));if(r.ok&&promise.active(state)){promise.record(state,title+' · perfectly accomplished','task','You began this task with purpose at midnight.');persist();if(r.title)r.title+=' · Perfect'}return r};promisePuzzleBefore(id,title,wrapped,again);if(promise.active(state)){const note=document.createElement('p');note.className='promise-quality';note.textContent='Midnight guides your hands. Every attempt finds its finest form.';$('modal').querySelector('h2').after(note);action('Let midnight perfect this task',()=>lifeResult(wrapped(puzzle.answer),again))}};
const promiseStoryBefore=lifeStoryScene;lifeStoryScene=function(){promiseStoryBefore();if(promise.active(state)&&$('modal').open){action('Ask midnight for the answer',()=>{const r=promise.fulfill(state,'answers');if(r.ok){lifeCommit();promiseOutcome(r)}else{const m=cityStory.current(state),inv=cityExperience.cases[state.silverStory.step];modal('The answer remains with you','<p>'+lifeEsc(inv?.solution||(m?.answer!==null?m?.choices[m.answer]:'Each person’s voice belongs in this story. Listen and choose with kindness.'))+'</p>');action('Continue with this answer',lifeContinue)}})}};
const promiseActionsBefore=cityBuildActions;cityBuildActions=function(){promiseActionsBefore();if(promise.active(state)){const card=cityCard('Everything finds its finest form','The whole county shares the enchantment. Make something wonderful, accomplish a goal, or uncover an answer.','Name my midnight intention',promiseBoard,'✦');$('comfortPlaces').prepend(card);cityCard('The county whispers an answer','Midnight brings the family’s next hidden truth into the light.','Ask the midnight county',()=>{const r=promise.fulfill(state,'answers');if(r.ok){lifeCommit();promiseOutcome(r)}else promiseBoard()},'☾')}};
const promisePeopleBefore=cityBuildPeople;cityBuildPeople=function(){promisePeopleBefore();if(promise.active(state)){const b=document.createElement('button');b.className='city-person';b.textContent='Whispers of Eldoria · the county is awake';b.onclick=promiseBoard;$('cityPeople').append(b)}};
const promisePersistBefore=persist;persist=function(){promise.observe(state);promisePersistBefore()};
const promiseDrawBefore=cityDraw;cityDraw=function(){promiseDrawBefore();promiseRender()};comfortDraw=cityDraw;
const promiseCraftBefore=craftScreen;craftScreen=function(){promiseCraftBefore();if(promise.active(state)){$('modal').insertAdjacentHTML('beforeend','<p class="promise-quality">Midnight will guide every cut, stitch and enchantment into a perfect pair.</p>')}};
const promisePotionBefore=potion;potion=function(){promisePotionBefore();if(promise.active(state))$('modal').insertAdjacentHTML('beforeend','<p class="promise-quality">The midnight light balances your ingredients. Your draught will be wonderful.</p>')};
window.ELDORIA_PROMISE={version:1,get active(){return promise.active(state)},openIntention:promiseBoard,openJournal:promiseJournal};
cityDraw();persist();setInterval(()=>{const old=promiseWasActive;promiseRender();if(old!==promiseWasActive)cityDraw()},1000);
